-- chair-step: the REVOKEs withdraw EXECUTE from public/anon/authenticated on the six functions this same file creates (server-only write path, declared in platform.client_callable_door); nothing that existed before is narrowed.
--
-- ops_check_run_and_item_2026_09_26d_write_path.sql
--
-- The write path into ops.check_run / ops.check_item (created by ops_check_run_and_item_2026_09_26.sql,
-- regenerated by _26b/_26c): six SECURITY DEFINER functions declared server-only, the `checks` knobs
-- they read, two retention policy rows, and the assertions that roll everything back unless both
-- tables are certified, admin-readable, lane-free and client-write-free. Emits no policy (no
-- sign-in freeze). Design and rules: the header of ops_check_run_and_item_2026_09_26.sql.
-- ── The write path ─────────────────────────────────────────────────────────────────────────────

-- The static catalog row for one declared check, by (repo, stable_id). Seeded from code once;
-- the row is the authority on cadence after that (only descriptive columns follow the code).
create or replace function ops.check_catalog_upsert(
  p_repo text, p_stable_id text, p_label text, p_command text, p_level text, p_category text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_sys constant uuid := '39c38960-d30c-4840-b0c1-c9960de95582';
  v_actor constant uuid := '87a6e699-3622-4869-8843-d0867456c0dd';
  v_id uuid;
  v_level text := case when p_level in ('error', 'warning', 'advisory') then p_level end;
  v_sha text;
  c ops.proof_check%rowtype;
begin
  if p_repo is null or p_repo not in ('matrx-frontend', 'aidream') then
    raise exception 'check_catalog_upsert: repo % is not matrx-frontend|aidream', p_repo using errcode = '22023';
  end if;
  if coalesce(btrim(p_stable_id), '') = '' then
    raise exception 'check_catalog_upsert: a static check needs its declared id (F8)' using errcode = '22023';
  end if;
  perform set_config('app.user_id', v_actor::text, true);
  select * into c from ops.proof_check where repo = p_repo and stable_id = p_stable_id;
  if not found then
    insert into ops.proof_check (
      slug, label, description, surface, source_app, source_feature, live_every_seconds,
      max_cost_usd, is_active, organization_id, created_by, kind, stable_id, repo, command, level)
    values (
      'static:' || p_repo || ':' || p_stable_id, coalesce(nullif(p_label, ''), p_stable_id),
      coalesce(nullif(p_label, ''), p_stable_id), 'static_check', p_repo,
      coalesce(nullif(p_category, ''), 'checks'), 3600, 0, true, v_sys, v_actor, 'static',
      p_stable_id, p_repo, p_command, v_level)
    returning * into c;
  elsif c.is_active is false
     or c.command is distinct from coalesce(p_command, c.command)
     or c.label is distinct from coalesce(nullif(p_label, ''), c.label)
     or c.level is distinct from coalesce(v_level, c.level) then
    update ops.proof_check
       set is_active = true,
           command = coalesce(p_command, command),
           label = coalesce(nullif(p_label, ''), label),
           description = coalesce(nullif(p_label, ''), description),
           level = coalesce(v_level, level)
     where id = c.id
    returning * into c;
  end if;
  select r.git_sha into v_sha from ops.check_run r where r.id = c.last_applied_run_id;
  return jsonb_build_object('id', c.id, 'itemized', c.itemized,
                            'last_applied_run_id', c.last_applied_run_id,
                            'last_applied_started_at', c.last_applied_started_at,
                            'last_applied_git_sha', v_sha);
end;
$function$;

-- One static check run, insert-once. p_run carries the check_run columns by name.
create or replace function ops.check_run_record(p_check_id uuid, p_run jsonb)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_sys constant uuid := '39c38960-d30c-4840-b0c1-c9960de95582';
  v_actor constant uuid := '87a6e699-3622-4869-8843-d0867456c0dd';
  v_id uuid;
begin
  if not exists (select 1 from ops.proof_check where id = p_check_id and kind = 'static') then
    raise exception 'check_run_record: % is not a static check in ops.proof_check', p_check_id using errcode = 'P0002';
  end if;
  perform set_config('app.user_id', v_actor::text, true);
  insert into ops.check_run (
    check_id, status, git_sha, host, started_at, finished_at, duration_ms, exit_code,
    new_count, known_count, findings_count, peak_rss_mb, skipped_reason, run_scope,
    scan_complete, verdict, headline, organization_id, created_by, visibility)
  values (
    p_check_id, p_run->>'status', p_run->>'git_sha', p_run->>'host',
    coalesce((p_run->>'started_at')::timestamptz, now()), (p_run->>'finished_at')::timestamptz,
    (p_run->>'duration_ms')::integer, (p_run->>'exit_code')::integer,
    coalesce((p_run->>'new_count')::integer, 0), coalesce((p_run->>'known_count')::integer, 0),
    coalesce((p_run->>'findings_count')::integer, 0), (p_run->>'peak_rss_mb')::integer,
    p_run->>'skipped_reason', coalesce(p_run->>'run_scope', 'partial'),
    coalesce((p_run->>'scan_complete')::boolean, false), p_run->>'verdict', left(p_run->>'headline', 500),
    v_sys, v_actor, 'internal')
  returning id into v_id;
  return v_id;
end;
$function$;

-- THE transition function (design §3.1). Idempotent per run; refuses a run older than the last
-- applied one (F7); fixes absent keys only on a full, scan-complete, completed run of an itemized
-- check (F6), behind a circuit breaker; a crash/timeout marks __check__ broken and touches no item
-- (F9); a fail verdict with no new item opens __summary__ (F9); a new key in a handed-off unit is
-- born handed_off (F10); a `db` accept never reopens from a run (F5); a fixed key that reappears is
-- revived. p_items: [{key, status new|known, basis accepted|debt, unit, title, file, line, rule}].
create or replace function ops.check_items_apply_run(
  p_run_id uuid, p_items jsonb, p_verdict text, p_headline text, p_confirm_mass_fix boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_sys constant uuid := '39c38960-d30c-4840-b0c1-c9960de95582';
  v_actor constant uuid := '87a6e699-3622-4869-8843-d0867456c0dd';
  r ops.check_run%rowtype;
  c ops.proof_check%rowtype;
  v_items jsonb := coalesce(p_items, '[]'::jsonb);
  v_bad text;
  v_share numeric;
  v_min integer;
  v_trash_days integer;
  v_itemized boolean;
  v_can_fix boolean;
  v_live integer;
  v_absent integer;
  v_new_reported integer;
  v_opened integer := 0;
  v_accepted integer := 0;
  v_reopened integer := 0;
  v_fixed integer := 0;
  v_trashed integer := 0;
  v_note text;
  v_summary_title text := left(coalesce(nullif(p_headline, ''), 'the check failed with no new item'), 500);
begin
  if p_verdict is not null and p_verdict not in ('pass', 'fail') then
    raise exception 'check_items_apply_run: verdict % is not pass|fail', p_verdict using errcode = '22023';
  end if;
  select * into r from ops.check_run where id = p_run_id for update;
  if not found then
    raise exception 'check_items_apply_run: no ops.check_run %', p_run_id using errcode = 'P0002';
  end if;
  -- Idempotent: a run is judged once. Applying it again (or re-sending a refused one) is a no-op.
  if r.applied or r.apply_note is not null then
    return jsonb_build_object('run_id', r.id, 'applied', r.applied, 'noop', true, 'note', r.apply_note);
  end if;
  perform set_config('app.user_id', v_actor::text, true);
  perform pg_advisory_xact_lock(hashtext('ops.check_item:' || r.check_id::text));
  select * into c from ops.proof_check where id = r.check_id for update;

  -- F7: never let an older run overwrite a newer verdict.
  if c.last_applied_started_at is not null and r.started_at < c.last_applied_started_at then
    v_note := format('refused: started %s, before the last applied run (%s started %s)',
                     r.started_at, c.last_applied_run_id, c.last_applied_started_at);
    update ops.check_run set skipped_reason = coalesce(skipped_reason, 'older_than_applied'), apply_note = v_note
     where id = r.id;
    return jsonb_build_object('run_id', r.id, 'applied', false, 'note', v_note);
  end if;
  if r.status = 'skipped' then
    v_note := 'skipped: ' || coalesce(r.skipped_reason, 'no reason given');
    update ops.check_run set apply_note = v_note where id = r.id;
    return jsonb_build_object('run_id', r.id, 'applied', false, 'note', v_note);
  end if;

  -- F9: a run that crashed, timed out or could not be parsed says nothing about its items.
  if r.status in ('errored', 'timed_out') then
    insert into ops.check_item (check_id, item_key, unit_key, state, title, first_seen_run_id,
                                last_transition_run_id, organization_id, created_by, visibility)
    values (c.id, '__check__', c.stable_id || '|__check__', 'check_broken',
            left(coalesce(nullif(p_headline, ''), 'the check ' || r.status), 500), r.id, r.id, v_sys, v_actor, 'internal')
    on conflict (check_id, item_key) do update
       set state = 'check_broken', title = excluded.title, last_transition_run_id = r.id,
           fixed_at = null, deleted_at = null, accept_basis = null
     where ops.check_item.state is distinct from 'check_broken' or ops.check_item.title is distinct from excluded.title;
    v_note := 'check_broken: ' || r.status;
    update ops.check_run set applied = true, apply_note = v_note where id = r.id;
    update ops.proof_check set last_applied_run_id = r.id, last_applied_started_at = r.started_at where id = c.id;
    return jsonb_build_object('run_id', r.id, 'applied', true, 'note', v_note);
  end if;

  select string_agg(format('%s (%s)', coalesce(i->>'key', '<none>'), e), '; ') into v_bad
    from (select i, case
                      when jsonb_typeof(i) <> 'object' then 'not an object'
                      when coalesce(btrim(i->>'key'), '') = '' then 'no key'
                      when char_length(i->>'key') > 300 then 'key longer than 300'
                      when i->>'key' in ('__check__', '__summary__') then 'reserved key'
                      when coalesce(i->>'status', 'new') not in ('new', 'known') then 'status not new|known'
                      when i->>'basis' is not null and i->>'basis' not in ('accepted', 'debt') then 'basis not accepted|debt'
                    end as e
            from jsonb_array_elements(v_items) i) x
   where e is not null;
  if v_bad is not null then
    raise exception 'check_items_apply_run: malformed items: %', left(v_bad, 1000) using errcode = '22023';
  end if;

  create temp table if not exists _check_reported (
    key text primary key, status text, basis text, unit text, title text, file text, line integer, rule text
  ) on commit drop;
  delete from _check_reported;
  insert into _check_reported
  select distinct on (i->>'key')
         i->>'key', coalesce(i->>'status', 'new'),
         case when coalesce(i->>'status', 'new') = 'known'
              then case i->>'basis' when 'accepted' then 'allowlist' else 'baseline' end end,
         coalesce(nullif(i->>'unit', ''), c.stable_id || '|' || coalesce(nullif(i->>'file', ''), nullif(i->>'rule', ''), i->>'key')),
         left(i->>'title', 500), i->>'file',
         case when jsonb_typeof(i->'line') = 'number' then (i->>'line')::integer end, i->>'rule'
    from jsonb_array_elements(v_items) i
   order by i->>'key', (coalesce(i->>'status', 'new') = 'new') desc;

  v_itemized := c.itemized or r.scan_complete or exists (select 1 from _check_reported);
  v_can_fix := r.run_scope = 'full' and r.scan_complete and r.status = 'completed' and v_itemized;
  select count(*), count(*) filter (where not exists (select 1 from _check_reported p where p.key = i.item_key))
    into v_live, v_absent
    from ops.check_item i
   where i.check_id = c.id and i.item_key not in ('__check__', '__summary__')
     and i.state in ('open', 'handed_off', 'accepted');
  select count(*) into v_new_reported from _check_reported where status = 'new';

  -- F6 circuit breaker: a run that would fix more than the knob share of the live items holds
  -- EVERYTHING and says so on __check__. The same rule catches a key-format change.
  v_share := coalesce((platform.knob_resolve('checks', 'fix_breaker_share', v_sys, null, null) #>> '{}')::numeric, 0.2);
  v_min := coalesce((platform.knob_resolve('checks', 'fix_breaker_min', v_sys, null, null) #>> '{}')::integer, 10);
  if v_can_fix and not p_confirm_mass_fix and v_absent > v_min and v_absent > v_share * v_live then
    v_note := format('circuit breaker: this run would mark %s of %s live items fixed (more than %s%% and more than %s); nothing was applied. Confirm the scan is whole, then re-apply with p_confirm_mass_fix.',
                     v_absent, v_live, round(v_share * 100), v_min);
    insert into ops.check_item (check_id, item_key, unit_key, state, title, first_seen_run_id,
                                last_transition_run_id, organization_id, created_by, visibility)
    values (c.id, '__check__', c.stable_id || '|__check__', 'check_broken', left(v_note, 500), r.id, r.id, v_sys, v_actor, 'internal')
    on conflict (check_id, item_key) do update
       set state = 'check_broken', title = excluded.title, last_transition_run_id = r.id,
           fixed_at = null, deleted_at = null, accept_basis = null;
    update ops.check_run set apply_note = v_note where id = r.id;
    return jsonb_build_object('run_id', r.id, 'applied', false, 'note', v_note, 'breaker', true);
  end if;

  -- New keys. A key in a unit somebody already holds is born held (F10).
  with ins as (
    insert into ops.check_item (check_id, item_key, unit_key, state, accept_basis, title, file, line, rule,
                                first_seen_run_id, last_transition_run_id, handed_off_at, handed_off_to,
                                organization_id, created_by, visibility)
    select c.id, p.key, p.unit,
           case when p.status = 'known' then 'accepted' when h.unit_key is not null then 'handed_off' else 'open' end,
           case when p.status = 'known' then p.basis end,
           p.title, p.file, p.line, p.rule, r.id, r.id,
           case when p.status = 'new' then h.handed_off_at end, case when p.status = 'new' then h.handed_off_to end,
           v_sys, v_actor, 'internal'
      from _check_reported p
      left join lateral (select x.unit_key, x.handed_off_at, x.handed_off_to from ops.check_item x
                          where x.unit_key = p.unit and x.state = 'handed_off' limit 1) h on true
     where not exists (select 1 from ops.check_item i where i.check_id = c.id and i.item_key = p.key)
    returning state
  )
  select count(*) filter (where state <> 'accepted'), count(*) filter (where state = 'accepted')
    into v_opened, v_accepted from ins;

  -- Known keys: covered by the check's own allowlist/baseline → accepted with that basis.
  with up as (
    update ops.check_item i
       set state = 'accepted', accept_basis = p.basis, review_after = null, db_accept_reason = null,
           handed_off_at = null, handed_off_to = null, fixed_at = null, deleted_at = null,
           last_transition_run_id = r.id, title = coalesce(p.title, i.title), file = coalesce(p.file, i.file),
           line = coalesce(p.line, i.line), unit_key = p.unit
      from _check_reported p
     where i.check_id = c.id and i.item_key = p.key and p.status = 'known'
       and (i.state <> 'accepted' or i.accept_basis is distinct from p.basis)
    returning 1
  )
  select v_accepted + count(*) into v_accepted from up;

  -- New keys that exist: reopen an allowlist/baseline accept (never a `db` one, F5), revive a
  -- fixed/retired/broken key; a key already open or held stays as it is.
  with up as (
    update ops.check_item i
       set state = case when exists (select 1 from ops.check_item x where x.unit_key = p.unit and x.state = 'handed_off')
                        then 'handed_off' else 'open' end,
           accept_basis = null, fixed_at = null, deleted_at = null, last_transition_run_id = r.id,
           title = coalesce(p.title, i.title), file = coalesce(p.file, i.file), line = coalesce(p.line, i.line),
           rule = coalesce(p.rule, i.rule), unit_key = p.unit
      from _check_reported p
     where i.check_id = c.id and i.item_key = p.key and p.status = 'new'
       and (i.state in ('fixed', 'check_retired', 'check_broken')
            or (i.state = 'accepted' and i.accept_basis <> 'db'))
    returning 1
  )
  select count(*) into v_reopened from up;

  -- Absent keys are fixed only by a run that can prove it saw everything (F6).
  if v_can_fix then
    with up as (
      update ops.check_item i
         set state = 'fixed', fixed_at = now(), deleted_at = now(), handed_off_at = null,
             handed_off_to = null, last_transition_run_id = r.id
       where i.check_id = c.id and i.item_key not in ('__check__', '__summary__')
         and i.state in ('open', 'handed_off', 'accepted')
         and not exists (select 1 from _check_reported p where p.key = i.item_key)
      returning 1
    )
    select count(*) into v_fixed from up;
  end if;

  -- A healthy run closes a broken check.
  update ops.check_item
     set state = 'fixed', fixed_at = now(), deleted_at = now(), last_transition_run_id = r.id
   where check_id = c.id and item_key = '__check__' and state = 'check_broken';

  -- F9: a failing verdict with no NEW item is still a failure — __summary__ carries it until a
  -- pass (or a new item that names the failure) closes it.
  if p_verdict = 'fail' and v_new_reported = 0 then
    insert into ops.check_item (check_id, item_key, unit_key, state, title, first_seen_run_id,
                                last_transition_run_id, organization_id, created_by, visibility)
    values (c.id, '__summary__', c.stable_id || '|__summary__', 'open', v_summary_title, r.id, r.id, v_sys, v_actor, 'internal')
    on conflict (check_id, item_key) do update
       set state = case when ops.check_item.state = 'handed_off' then 'handed_off' else 'open' end,
           title = excluded.title, fixed_at = null, deleted_at = null, accept_basis = null,
           last_transition_run_id = case when ops.check_item.state in ('open', 'handed_off')
                                         then ops.check_item.last_transition_run_id else r.id end;
  else
    update ops.check_item
       set state = 'fixed', fixed_at = now(), deleted_at = now(), handed_off_at = null, handed_off_to = null,
           last_transition_run_id = r.id
     where check_id = c.id and item_key = '__summary__' and state in ('open', 'handed_off');
  end if;

  -- F2: bounded growth by construction — trash this check's old runs (the sweep purges them).
  v_trash_days := coalesce((platform.knob_resolve('checks', 'check_run_trash_days', v_sys, null, null) #>> '{}')::integer, 30);
  with up as (
    update ops.check_run set deleted_at = now()
     where check_id = c.id and deleted_at is null and started_at < now() - make_interval(days => v_trash_days)
    returning 1
  )
  select count(*) into v_trashed from up;

  v_note := format('opened %s, accepted %s, reopened %s, fixed %s%s', v_opened, v_accepted, v_reopened, v_fixed,
                   case when not v_can_fix then ' (absent keys not judged: ' ||
                     concat_ws(', ',
                       case when r.run_scope <> 'full' then 'partial run' end,
                       case when not r.scan_complete then 'no end-of-scan marker' end,
                       case when not v_itemized then 'check is not itemized' end) || ')' else '' end);
  update ops.check_run set applied = true, apply_note = v_note where id = r.id;
  update ops.proof_check
     set last_applied_run_id = r.id, last_applied_started_at = r.started_at,
         itemized = v_itemized,
         -- F13: the verdict columns move only when the verdict changes.
         last_verdict = case when p_verdict is distinct from last_verdict and p_verdict is not null then p_verdict else last_verdict end,
         last_run_at = case when p_verdict is distinct from last_verdict and p_verdict is not null then coalesce(r.finished_at, r.started_at) else last_run_at end
   where id = c.id;
  return jsonb_build_object('run_id', r.id, 'applied', true, 'opened', v_opened, 'accepted', v_accepted,
                            'reopened', v_reopened, 'fixed', v_fixed, 'trashed_runs', v_trashed,
                            'fix_judged', v_can_fix, 'note', v_note);
end;
$function$;

-- The claim is held at UNIT level: every open item in the unit changes together (F10).
create or replace function ops.check_items_hand_off(p_unit_key text, p_to text)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_n integer;
begin
  if coalesce(btrim(p_to), '') = '' then
    raise exception 'check_items_hand_off: name who takes the unit' using errcode = '22023';
  end if;
  perform set_config('app.user_id', '87a6e699-3622-4869-8843-d0867456c0dd', true);
  if exists (select 1 from ops.check_item where unit_key = p_unit_key and state = 'handed_off') then
    raise exception 'check_items_hand_off: unit % is already handed off', p_unit_key using errcode = '55006';
  end if;
  update ops.check_item set state = 'handed_off', handed_off_at = now(), handed_off_to = p_to
   where unit_key = p_unit_key and state = 'open';
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$;

create or replace function ops.check_items_release(p_unit_key text, p_reason text)
returns integer
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_n integer;
begin
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'check_items_release: say why the unit is released' using errcode = '22023';
  end if;
  perform set_config('app.user_id', '87a6e699-3622-4869-8843-d0867456c0dd', true);
  update ops.check_item
     set state = 'open', handed_off_at = null, handed_off_to = null,
         metadata = metadata || jsonb_build_object('released_at', now(), 'release_reason', p_reason)
   where unit_key = p_unit_key and state = 'handed_off';
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$;

-- A DB-only accept, for an item with no repo home (C1). It never reopens from a run (F5); its
-- review date is required, and is the one thing that reopens it.
create or replace function ops.check_item_db_accept(
  p_check_id uuid, p_item_key text, p_reason text, p_review_after timestamptz)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_id uuid;
begin
  if coalesce(btrim(p_reason), '') = '' or p_review_after is null then
    raise exception 'check_item_db_accept: a reason and a review date are both required' using errcode = '22023';
  end if;
  if p_item_key in ('__check__', '__summary__') then
    raise exception 'check_item_db_accept: % is a failure record, not an item — it cannot be accepted', p_item_key using errcode = '22023';
  end if;
  perform set_config('app.user_id', '87a6e699-3622-4869-8843-d0867456c0dd', true);
  update ops.check_item
     set state = 'accepted', accept_basis = 'db', db_accept_reason = p_reason, review_after = p_review_after,
         handed_off_at = null, handed_off_to = null, fixed_at = null, deleted_at = null
   where check_id = p_check_id and item_key = p_item_key and state in ('open', 'handed_off', 'accepted')
  returning id into v_id;
  if v_id is null then
    raise exception 'check_item_db_accept: no live item % on check %', p_item_key, p_check_id using errcode = 'P0002';
  end if;
  return v_id;
end;
$function$;

do $grants$
declare
  f text;
begin
  foreach f in array array[
    'ops.check_catalog_upsert(text, text, text, text, text, text)',
    'ops.check_run_record(uuid, jsonb)',
    'ops.check_items_apply_run(uuid, jsonb, text, text, boolean)',
    'ops.check_items_hand_off(text, text)',
    'ops.check_items_release(text, text)',
    'ops.check_item_db_accept(uuid, text, text, timestamptz)'
  ] loop
    -- The access decision, declared in data: server-only, no client caller ever.
    insert into platform.client_callable_door (schema_name, function_name, identity_args, identity_argtypes,
                                               reason, declared_by, non_client_lane, signed_in_callers, anonymous_callers)
    select n.nspname, p.proname, pg_get_function_identity_arguments(p.oid),
           -- 1-based (an oidvector cast keeps its 0 lower bound, which the door's check cannot match)
           (select coalesce(array_agg(t order by o), '{}'::oid[]) from unnest(p.proargtypes) with ordinality u(t, o)),
           'Checks store write path (P2-STORAGE-DESIGN §3). Entity-id arguments (check ids, run ids) are checked against ops.proof_check / ops.check_run by the function itself; no caller identity is involved because no client may call it.',
           'matrx-frontend/migrations/ops_check_run_and_item_2026_09_26.sql',
           'server_only: aidream/services/platform_checks/ingest.py (the hand-run check ingest, as the service connection) is the only caller; findings are platform-admin-only internal records, so no browser or signed-in client ever writes them.',
           false, false
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where p.oid = f::regprocedure
       and not exists (select 1 from platform.client_callable_door d
                        where d.schema_name = n.nspname and d.function_name = p.proname
                          and d.identity_args = pg_get_function_identity_arguments(p.oid));
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end
$grants$;

-- ── Knobs the transition function reads (feature `checks`) ────────────────────────────────────
insert into platform.feature_knob (feature, key, value, default_value, value_type, unit, min_value, max_value,
                                   label, description, set_by, basis, review_due, overridable_by)
values
  ('checks', 'fix_breaker_share', to_jsonb(0.2), to_jsonb(0.2), 'number', 'share', 0.01, 1,
   'Mass-fix breaker: share of live items',
   'A single check run may mark at most this share of that check''s live findings fixed; past it (and past the minimum count), nothing from the run applies and the check shows as broken until someone confirms.',
   'agent', 'P2-STORAGE-ATTACK F6: a truncated scan (1,000 of 3,800 items) must never close 2,800 findings. 20% lets a normal fix wave through and holds a lost scan.',
   date '2026-12-26', '{}'),
  ('checks', 'fix_breaker_min', to_jsonb(10), to_jsonb(10), 'integer', 'items', 0, 100000,
   'Mass-fix breaker: minimum count',
   'The breaker only trips when a run would fix more than this many findings at once, so a small check fixing its last few items is never held.',
   'agent', 'P2-STORAGE-ATTACK F6; below ten items a false fix is cheap to see and undo.',
   date '2026-12-26', '{}'),
  ('checks', 'check_run_trash_days', to_jsonb(30), to_jsonb(30), 'integer', 'days', 1, 365,
