   date '2026-12-26', '{}')
on conflict (feature, key) do nothing;

-- ── Retention policy rows (F2): inert until the lifecycle sweep's gate opens ─────────────────
insert into platform.retention_policy (scope, entity_token, organization_id, trigger_kind, mode, retention_days,
                                       label, description, basis, set_by, review_due)
select v.scope, v.token, '39c38960-d30c-4840-b0c1-c9960de95582'::uuid, 'soft_deleted', 'purge', v.days,
       v.label, v.description, v.basis, 'agent', date '2027-03-26'
  from (values
    ('entity', 'ops_check_run', 7, 'Check run log retention',
     'Purges a check run 7 days after it was trashed (its check trashes runs older than 30 days on each run).',
     'P2-STORAGE-DESIGN §3: the run log is bounded by the writer; a week in the trash covers any recovery.'),
    ('entity', 'ops_check_item', 90, 'Fixed check finding retention',
     'Purges a fixed finding 90 days after it was fixed. A finding that comes back before then is revived with its history.',
     'P2-STORAGE-DESIGN §3: fixed rows are the only trashed check_item rows; 90 days keeps "this came back" visible for a quarter.')
  ) as v(scope, token, days, label, description, basis)
 where not exists (select 1 from platform.retention_policy p where p.entity_token = v.token and p.organization_id = '39c38960-d30c-4840-b0c1-c9960de95582'::uuid);

-- ── In-file assertions: roll everything back unless each holds ────────────────────────────────
do $assert$
declare
  t text;
  v_ok boolean;
begin
  foreach t in array array['check_run', 'check_item'] loop
    select iam.canonical_certify_ok('ops', t, 'ops_' || t) into v_ok;
    if not v_ok then
      raise exception 'ops.% is not canonical-certified: %', t,
        (select string_agg(x::text, '; ') from iam.verify_canonical('ops', t, 'ops_' || t, 'system') x);
    end if;
    if not exists (select 1 from pg_policy where polrelid = ('ops.' || t)::regclass and polname = 'platform_admin_read') then
      raise exception 'ops.% has no platform_admin_read — our own admin database access is required', t;
    end if;
    if exists (select 1 from pg_policy where polrelid = ('ops.' || t)::regclass
                and pg_get_expr(polqual, polrelid) ilike '%global_readable%') then
      raise exception 'ops.% carries the global_readable system-org lane (F1)', t;
    end if;
    if has_table_privilege('authenticated', ('ops.' || t)::regclass, 'INSERT')
       or has_table_privilege('authenticated', ('ops.' || t)::regclass, 'UPDATE')
       or has_table_privilege('authenticated', ('ops.' || t)::regclass, 'DELETE')
       or has_table_privilege('anon', ('ops.' || t)::regclass, 'INSERT') then
      raise exception 'ops.% still grants a client write privilege (F4)', t;
    end if;
  end loop;
end
$assert$;

notify pgrst, 'reload schema';
